import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { ChipRootInstance } from './ChipRoot.types';
/**
 * Defines passthrough(pt) options type in ChipEnd component.
 */
export type ChipEndPassThroughType<E> = PassThroughType<ChipEndInstance, E>;
/**
 * Defines passthrough(pt) options of ChipEnd component.
 */
export interface ChipEndPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: ChipEndPassThroughType<React.HTMLAttributes<HTMLSpanElement>>;
}
/**
 * Defines valid properties in ChipEnd component.
 */
export interface ChipEndProps extends BaseComponentProps<ChipEndInstance, unknown, ChipEndPassThrough> {
}
/**
 * Defines valid state in ChipEnd component.
 */
export interface ChipEndState {
}
/**
 * Defines the methods and properties exposed by ChipEnd component.
 */
export interface ChipEndExposes {
    /**
     * The Chip component instance.
     */
    chip: ChipRootInstance | undefined | null;
}
/**
 * Instance of ChipEnd component.
 */
export type ChipEndInstance = ComponentInstance<ChipEndProps, ChipEndState, ChipEndExposes>;
